-- MVP schema (spec section 7). Phase 2 and 3 entities (clinical history, expenses, lost and found,
-- reports, volunteers, members) arrive in later migrations. Domain terms: see docs/glossary.md.
--
-- Conventions
--   names      English, singular, snake_case. Spanish only for user-facing copy, never in the schema.
--   ids        TEXT, generated by the app (crypto.randomUUID()): public URLs never expose a counter.
--   booleans   INTEGER 0 or 1.
--   dates      TEXT in ISO 8601 UTC. Calendar dates ('*_on') are 'YYYY-MM-DD'; instants ('*_at') are timestamps.
--   money      INTEGER, whole Argentine pesos.
--   JSON       TEXT holding a JSON document.
--   enums      CHECK constraints. Changing one later means rebuilding the table, so lists follow the spec.
--   discarded_at marks soft deletion on tables that hold personal data.

CREATE TABLE app_user (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('superadmin', 'admin', 'editor', 'veterinarian', 'municipality')),
  last_seen_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  discarded_at TEXT
) STRICT;

CREATE TABLE person (
  id TEXT PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  whatsapp_phone TEXT,
  email TEXT,
  city TEXT,
  neighborhood TEXT,
  address TEXT,
  national_id TEXT,
  data_consent_at TEXT NOT NULL,
  data_consent_version TEXT NOT NULL,
  preferred_channel TEXT CHECK (preferred_channel IN ('whatsapp', 'email', 'phone')),
  internal_notes TEXT,
  tags TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  discarded_at TEXT,
  CHECK (json_valid(tags))
) STRICT;

CREATE INDEX person_email ON person (email) WHERE email IS NOT NULL;
CREATE INDEX person_whatsapp_phone ON person (whatsapp_phone) WHERE whatsapp_phone IS NOT NULL;

CREATE TABLE animal (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  species TEXT NOT NULL CHECK (species IN ('dog', 'cat', 'other')),
  sex TEXT NOT NULL CHECK (sex IN ('male', 'female', 'unknown')),
  approx_birth_date TEXT,
  age_category TEXT CHECK (age_category IN ('baby', 'young', 'adult', 'senior')),
  size TEXT NOT NULL CHECK (size IN ('small', 'medium', 'large')),
  color TEXT,
  approx_breed TEXT,
  story TEXT,
  personality TEXT NOT NULL DEFAULT '[]',
  good_with_dogs TEXT NOT NULL DEFAULT 'unknown' CHECK (good_with_dogs IN ('yes', 'no', 'unknown')),
  good_with_cats TEXT NOT NULL DEFAULT 'unknown' CHECK (good_with_cats IN ('yes', 'no', 'unknown')),
  good_with_kids TEXT NOT NULL DEFAULT 'unknown' CHECK (good_with_kids IN ('yes', 'no', 'unknown')),
  neutered INTEGER NOT NULL DEFAULT 0 CHECK (neutered IN (0, 1)),
  vaccinated INTEGER NOT NULL DEFAULT 0 CHECK (vaccinated IN (0, 1)),
  dewormed INTEGER NOT NULL DEFAULT 0 CHECK (dewormed IN (0, 1)),
  microchip TEXT,
  status TEXT NOT NULL DEFAULT 'intake' CHECK (
    status IN (
      'intake', 'under_treatment', 'available', 'reserved', 'adopted',
      'fostered', 'deceased', 'returned', 'not_adoptable'
    )
  ),
  urgent INTEGER NOT NULL DEFAULT 0 CHECK (urgent IN (0, 1)),
  intake_date TEXT,
  intake_reason TEXT CHECK (intake_reason IN ('rescue', 'raid', 'abandonment', 'surrender')),
  current_location TEXT CHECK (current_location IN ('shelter', 'foster', 'vet')),
  published INTEGER NOT NULL DEFAULT 0 CHECK (published IN (0, 1)),
  special_requirements TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (json_valid(personality))
) STRICT;

-- Public catalog: published animals that are available or reserved, urgent first, then oldest first.
CREATE INDEX animal_catalog ON animal (urgent DESC, intake_date) WHERE published = 1 AND status IN ('available', 'reserved');
CREATE INDEX animal_status ON animal (status);

CREATE TABLE photo (
  id TEXT PRIMARY KEY,
  animal_id TEXT NOT NULL REFERENCES animal (id) ON DELETE CASCADE,
  r2_key TEXT NOT NULL UNIQUE,
  position INTEGER NOT NULL DEFAULT 0,
  alt_text TEXT NOT NULL,
  width INTEGER,
  height INTEGER,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  usage_consent INTEGER NOT NULL DEFAULT 1 CHECK (usage_consent IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX photo_animal ON photo (animal_id, position);
CREATE UNIQUE INDEX photo_one_primary_per_animal ON photo (animal_id) WHERE is_primary = 1;

CREATE TABLE animal_status_history (
  id TEXT PRIMARY KEY,
  animal_id TEXT NOT NULL REFERENCES animal (id) ON DELETE CASCADE,
  previous_status TEXT,
  new_status TEXT NOT NULL,
  user_id TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX animal_status_history_animal ON animal_status_history (animal_id, created_at);

-- An adoption or foster request from a visitor.
CREATE TABLE application (
  id TEXT PRIMARY KEY,
  person_id TEXT NOT NULL REFERENCES person (id),
  animal_id TEXT REFERENCES animal (id),
  type TEXT NOT NULL CHECK (type IN ('adoption', 'foster')),
  answers TEXT NOT NULL,
  prescreen_result TEXT CHECK (prescreen_result IN ('eligible', 'review', 'ineligible')),
  stage TEXT NOT NULL DEFAULT 'new' CHECK (
    stage IN ('new', 'in_review', 'interview', 'approved', 'delivered', 'rejected', 'withdrawn')
  ),
  rejection_reason TEXT,
  assigned_to TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  discarded_at TEXT,
  CHECK (json_valid(answers)),
  CHECK (stage NOT IN ('rejected', 'withdrawn') OR rejection_reason IS NOT NULL)
) STRICT;

CREATE INDEX application_stage ON application (stage, created_at);
CREATE INDEX application_animal ON application (animal_id);
CREATE INDEX application_person ON application (person_id);

-- One row per stage change: the spec asks for the date of each stage.
CREATE TABLE application_stage_history (
  id TEXT PRIMARY KEY,
  application_id TEXT NOT NULL REFERENCES application (id) ON DELETE CASCADE,
  stage TEXT NOT NULL,
  user_id TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX application_stage_history_application ON application_stage_history (application_id, created_at);

CREATE TABLE adoption (
  id TEXT PRIMARY KEY,
  animal_id TEXT NOT NULL REFERENCES animal (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  application_id TEXT NOT NULL UNIQUE REFERENCES application (id),
  delivered_on TEXT NOT NULL,
  contract_r2_key TEXT,
  neutering_commitment_on TEXT,
  returned INTEGER NOT NULL DEFAULT 0 CHECK (returned IN (0, 1)),
  returned_on TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (returned = 1 OR returned_on IS NULL)
) STRICT;

CREATE INDEX adoption_animal ON adoption (animal_id);
CREATE INDEX adoption_person ON adoption (person_id);

CREATE TABLE foster_placement (
  id TEXT PRIMARY KEY,
  animal_id TEXT NOT NULL REFERENCES animal (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  started_on TEXT NOT NULL,
  ended_on TEXT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (ended_on IS NULL OR ended_on >= started_on)
) STRICT;

-- An animal is in at most one foster placement at a time.
CREATE UNIQUE INDEX foster_placement_one_active_per_animal ON foster_placement (animal_id) WHERE ended_on IS NULL;
CREATE INDEX foster_placement_person ON foster_placement (person_id);

CREATE TABLE follow_up (
  id TEXT PRIMARY KEY,
  adoption_id TEXT REFERENCES adoption (id) ON DELETE CASCADE,
  foster_placement_id TEXT REFERENCES foster_placement (id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN ('day_7', 'day_30', 'month_6', 'neutering', 'other')),
  scheduled_on TEXT NOT NULL,
  completed_on TEXT,
  result TEXT CHECK (result IN ('ok', 'problems', 'no_response', 'returned')),
  notes TEXT,
  completed_by TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK ((adoption_id IS NULL) <> (foster_placement_id IS NULL)),
  CHECK (completed_on IS NULL OR result IS NOT NULL)
) STRICT;

-- Dashboard: pending and overdue follow-ups.
CREATE INDEX follow_up_pending ON follow_up (scheduled_on) WHERE completed_on IS NULL;

-- A fundraising goal with a public progress bar (spec 6.5).
CREATE TABLE goal (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  description TEXT,
  target_amount INTEGER NOT NULL CHECK (target_amount > 0),
  currency TEXT NOT NULL DEFAULT 'ARS',
  deadline_on TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'fulfilled', 'closed')),
  image_r2_key TEXT,
  mercado_pago_url TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE goal_animal (
  goal_id TEXT NOT NULL REFERENCES goal (id) ON DELETE CASCADE,
  animal_id TEXT NOT NULL REFERENCES animal (id) ON DELETE CASCADE,
  PRIMARY KEY (goal_id, animal_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE donation (
  id TEXT PRIMARY KEY,
  goal_id TEXT REFERENCES goal (id),
  amount INTEGER NOT NULL CHECK (amount > 0),
  donated_on TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('alias', 'cbu', 'mp_link', 'mp_api', 'cash')),
  donor_person_id TEXT REFERENCES person (id),
  public_name TEXT,
  anonymous INTEGER NOT NULL DEFAULT 0 CHECK (anonymous IN (0, 1)),
  external_reference TEXT,
  recorded_by TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (anonymous = 0 OR public_name IS NULL)
) STRICT;

CREATE INDEX donation_goal ON donation (goal_id, donated_on);
-- Idempotency for Mercado Pago webhooks: the same external payment is stored once.
CREATE UNIQUE INDEX donation_external_reference ON donation (external_reference) WHERE external_reference IS NOT NULL;

-- Progress shown on the public goal bar, computed so it cannot drift from the donations.
CREATE VIEW goal_progress AS
SELECT
  goal.id AS goal_id,
  COALESCE(SUM(donation.amount), 0) AS current_amount,
  COUNT(donation.id) AS contributions,
  MAX(donation.donated_on) AS last_donated_on
FROM goal
LEFT JOIN donation ON donation.goal_id = goal.id
GROUP BY goal.id;

CREATE TABLE news_post (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  body TEXT NOT NULL,
  image_r2_key TEXT,
  tags TEXT NOT NULL DEFAULT '[]',
  published_at TEXT,
  author_id TEXT REFERENCES app_user (id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (json_valid(tags))
) STRICT;

CREATE INDEX news_post_published ON news_post (published_at DESC) WHERE published_at IS NOT NULL;

CREATE TABLE news_post_animal (
  news_post_id TEXT NOT NULL REFERENCES news_post (id) ON DELETE CASCADE,
  animal_id TEXT NOT NULL REFERENCES animal (id) ON DELETE CASCADE,
  PRIMARY KEY (news_post_id, animal_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE agenda_event (
  id TEXT PRIMARY KEY,
  type TEXT NOT NULL CHECK (
    type IN ('neutering', 'vaccination', 'deworming', 'adoption_day', 'fair', 'bingo')
  ),
  title TEXT NOT NULL,
  starts_at TEXT NOT NULL,
  ends_at TEXT,
  venue_name TEXT,
  public_address TEXT,
  neighborhood TEXT,
  organizer TEXT NOT NULL CHECK (organizer IN ('funpabia', 'municipality', 'zoonosis', 'other')),
  requirements TEXT,
  appointment_url TEXT,
  appointment_phone TEXT,
  source TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (ends_at IS NULL OR ends_at >= starts_at)
) STRICT;

CREATE INDEX agenda_event_starts_at ON agenda_event (starts_at);

-- Alias, CBU, texts, social links and the adoption pre-screen rules (spec 6.2, MVP).
CREATE TABLE setting (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT, WITHOUT ROWID;

CREATE TABLE audit_log (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES app_user (id),
  entity TEXT NOT NULL CHECK (entity IN ('animal', 'application', 'donation', 'expense')),
  entity_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('create', 'update', 'delete')),
  changes TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  CHECK (json_valid(changes))
) STRICT;

CREATE INDEX audit_log_entity ON audit_log (entity, entity_id, created_at);
